<?php use Namira\{Security,Env,DataBackup}; ?>
<section class="panel"><h2>پشتیبان پایگاه داده</h2><p>پیش از ارتقای ساختار، یک نسخه SQL خصوصی به‌صورت خودکار ذخیره می‌شود. این فایل شامل اطلاعات و جدول‌های پایگاه داده است؛ پشتیبان فایل‌های اصلی تصاویر باید جداگانه از File Manager یا پشتیبان هاست تهیه شود.</p><form method="post"><?= Security::field() ?><input type="hidden" name="action" value="backup-create"><button class="primary">ساخت پشتیبان اکنون</button></form></section>
<div class="panel table-scroll"><h2>نسخه‌های ذخیره‌شده</h2><table><thead><tr><th>تاریخ</th><th>علت</th><th>حجم</th><th>صحت فایل</th><th>دریافت خصوصی</th></tr></thead><tbody>
<?php $files=glob(Env::storage().'/backups/db-*.json')?:[];rsort($files);foreach(array_slice($files,0,30) as $file):$b=json_decode((string)file_get_contents($file),true);if(!is_array($b))continue;$name=basename($file,'.json');$sql=dirname($file).'/'.$name.'.sql';$valid=is_file($sql)&&hash_equals($b['sha256']??'',hash_file('sha256',$sql)); ?>
<tr><td><?= e($b['created_at']??$name) ?></td><td><?= e($b['reason']??'') ?></td><td><?= fa(round(($b['bytes']??0)/1048576,2)) ?> مگابایت</td><td><?= $valid?'SHA-256 تأیید شد':'نیازمند بررسی' ?></td><td><?php if($valid): ?><a class="outline" href="<?= e(url('backup-download',['name'=>$name])) ?>">دریافت SQL</a><?php endif ?></td></tr><?php endforeach ?><?php if(!$files): ?><tr><td colspan="5">هنوز نسخه‌ای در این نصب ذخیره نشده است.</td></tr><?php endif ?></tbody></table></div>
<section class="panel"><h2>وضعیت نصب</h2><dl><dt>ساختار سامانه</dt><dd>003 — بانک هنرمندان و رسانه‌های مرتبط</dd><dt>اتصال پرداخت</dt><dd><?= Env::get('PAYMENT_DRIVER','disabled')==='test'?'آزمایشی؛ اتصال بانکی واقعی فعال نیست':'غیرفعال؛ اتصال بانکی واقعی ارائه نشده است' ?></dd><dt>بازیابی</dt><dd>بازیابی SQL باید ابتدا روی یک پایگاه داده مستقل آزمایش و سپس با پشتیبان هاست انجام شود. این صفحه داده زنده را بازنویسی نمی‌کند.</dd></dl></section>
